patch.replace:
def _last_price_ext(ticker: str, max_age_min: float = 20.0):
    """A REAL pre/post-market print (prepost bars), no older than max_age_min. Returns None when
    nothing fresh is trading off-hours — an honest 'no fill possible', never a stale regular
    close dressed up as a quote. Thin names simply don't fill until the open."""
    if not _HAVE_YF:
        return None
    try:
        h = yf.Ticker(ticker).history(period="1d", interval="1m", prepost=True)
        if len(h):
            last_ts = h.index[-1].timestamp()
            if time.time() - last_ts <= max_age_min * 60:
                return float(h["Close"].iloc[-1])
            # Fallback: if the most recent bar is stale, scan backwards for the freshest bar
            # within the window. This handles cases where yfinance returns a mix of stale regular-
            # session bars and fresh pre/post bars but the last bar happens to be stale.
            for i in range(len(h) - 1, -1, -1):
                bar_ts = h.index[i].timestamp()
                if bar_ts <= last_ts - max_age_min * 60:
                    break
                if time.time() - bar_ts <= max_age_min * 60:
                    return float(h["Close"].iloc[i])
    except Exception:
        pass
    return None

