def _wilson_interval(wins: int, n: int, z: float = 1.64) -> tuple[float, float]:
    """Return (lower, upper) Wilson score interval in one pass.

    Caller: PatternMemory.is_loser and any future graduation logic that needs both bounds.
    Avoids duplicate math.sqrt / division work when both bounds are required.
    """
    if n == 0:
        return 0.0, 1.0
    p = wins / n
    z2n = z * z / n
    d = 1 + z2n
    c = p + z2n / 2.0
    m = z * math.sqrt((p * (1 - p) + z2n / 4.0) / n)
    return max(0.0, (c - m) / d), min(1.0, (c + m) / d)

