def _check_milestones(self):
    """Check if current equity crossed a new power-of-10 milestone and record it.
    Only fires once per milestone; milestones are additive and never removed.
    Called after every equity update so the mother's ambition ratchets up automatically."""
    if self.dead:
        return
    mult = self.state["paper_equity"] / self.start if self.start else 0
    if mult < 1.0:
        return
    # Find the highest power-of-10 multiple reached (1x, 10x, 100x, ...)
    power = int(math.log10(mult)) if mult > 0 else 0
    milestone = f"x{10 ** power}"
    if milestone not in self.state.get("milestones", []):
        self.state.setdefault("milestones", []).append(milestone)
        self._escalate_target()
        self._save_state()

