def trust(self) -> float:
    """How much to trust the model's edge for sizing — 0 at (or worse than) the NO-SKILL Brier,
    rising toward 1 as calibration genuinely beats it. AUDIT FIX: the no-skill floor depends on the
    label base rate — always predicting the majority class gives Brier = base*(1-base)."""
    no_skill = self.base * (1.0 - self.base)
    if self.brier >= no_skill:
        return 0.0
    # Scale so trust=1 when brier=0 (perfect), 0 when brier=no_skill
    return max(0.0, min(1.0, (no_skill - self.brier) / no_skill))

